+    li.dataset.correct=o.c?'true':'false';li.dataset.why=o.w;li.textContent=o.t;
+    if(prev)li.classList.add('lk');
+    li.addEventListener('click',()=>{
+      if(li.classList.contains('lk'))return;
+      list.querySelectorAll('li').forEach(x=>x.classList.add('lk'));
+      const ok=li.dataset.correct==='true';
+      li.classList.add(ok?'ok':'no');
+      if(!ok)list.querySelectorAll('[data-correct="true"]').forEach(x=>x.classList.add('ok'));
+      mcR[q.id]=ok?'ok':'no';
+      fb.style.display='block';fb.className='mfb '+(ok?'ok':'no');
+      fb.textContent=(ok?'✓ Correct. ':'✗ Not quite. ')+li.dataset.why;
+    });
+    li.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')li.click();});
+    list.appendChild(li);
+  });
+  if(prev){fb.style.display='block';fb.className='mfb '+(prev==='ok'?'ok':'no');
+    fb.textContent=prev==='ok'?'✓ Marked correct.':'✗ Marked incorrect.';}
+}
+
+function renderW(q){
+  const sv=saved[q.id]||{};
+  document.getElementById('wa').value=sv.t||'';
+  const kr=document.getElementById('kr');kr.style.display=sv.kr?'block':'none';
+  if(sv.kr){document.getElementById('kt').innerHTML=sv.kr.tally;document.getElementById('kc').innerHTML=sv.kr.chips;}
+  document.getElementById('md').style.display=sv.ms?'block':'none';
+  if(sv.ms)document.getElementById('mt').textContent=q.m;
+  document.getElementById('sr').style.display=sv.ms?'flex':'none';
+}
+
+function saveW(){
+  const q=qs[idx];if(!q||q.type!=='w')return;
+  if(!saved[q.id])saved[q.id]={};
+  saved[q.id].t=document.getElementById('wa').value;
+}
+
+function chkW(){
+  const q=qs[idx];
+  const txt=(document.getElementById('wa').value||'').toLowerCase();
+  const hits=q.c.map(c=>({l:c.l,h:c.t.some(t=>txt.includes(t.toLowerCase()))}));
+  const got=hits.filter(h=>h.h).length;
+  const tally=`<strong>${got} / ${hits.length} key concepts detected</strong>`;
+  const chips=hits.map(h=>`<span class="kc ${h.h?'h':'m'}">${h.h?'✓':'✗'} ${h.l}</span>`).join('');
+  document.getElementById('kt').innerHTML=tally;
+  document.getElementById('kc').innerHTML=chips;
+  document.getElementById('kr').style.display='block';
+  if(!saved[q.id])saved[q.id]={};
+  saved[q.id].kr={tally,chips};
+  saved[q.id].t=document.getElementById('wa').value;
+}
+
+function showM(){
+  const q=qs[idx];
+  document.getElementById('mt').textContent=q.m;
+  document.getElementById('md').style.display='block';
+  document.getElementById('sr').style.display='flex';
+  if(!saved[q.id])saved[q.id]={};
+  saved[q.id].ms=true;
+  saved[q.id].t=document.getElementById('wa').value;
+}
+
+function rate(v){
+  wR[qs[idx].id]=v;
+  if(!saved[qs[idx].id])saved[qs[idx].id]={};
+  saved[qs[idx].id].rate=v;
