+  const tgt=v==='k'?document.getElementById('sr').children[1]:document.getElementById('sr').children[2];
+  if(tgt)tgt.style.opacity='1';
+}
+
+function prev(){saveW();if(idx>0){idx--;render();}}
+function next(){saveW();if(idx<qs.length-1){idx++;render();}}
+
+function results(){
+  saveW();
+  const mcTotal=qs.filter(q=>q.type==='mc').length;
+  const mcOk=Object.values(mcR).filter(v=>v==='ok').length;
+  const pct=mcTotal?Math.round(mcOk/mcTotal*100):0;
+  document.getElementById('rb').textContent=`${mcOk}/${mcTotal}`;
+  document.getElementById('rl').textContent=(pct===100?'🎉 Perfect MC score!':pct>=60?`${pct}% — review misses below`:`${pct}% — re-read lesson 0013`)+` · Written: see self-ratings`;
+
+  const misses=qs.filter(q=>q.type==='mc'&&mcR[q.id]==='no');
+  const rm=document.getElementById('rm');
+  rm.innerHTML=misses.length?misses.map(q=>`<div class="miss">${q.q.slice(0,75)}…<span class="mcorr">✓ ${q.opts.find(o=>o.c).t.slice(0,55)}</span></div>`).join(''):'<em style="color:var(--dim);font-size:.84rem">None!</em>';
+
+  const revW=qs.filter(q=>q.type==='w'&&wR[q.id]==='r');
+  const rw=document.getElementById('rw');
+  rw.innerHTML=revW.length?revW.map(q=>`<div class="miss">${q.q.slice(0,75)}…</div>`).join(''):'<em style="color:var(--dim);font-size:.84rem">None flagged.</em>';
+
+  show('R');
+}
+
+function rev(){
+  const mc=qs.filter(q=>q.type==='mc'&&mcR[q.id]==='no');
+  const wr=qs.filter(q=>q.type==='w'&&wR[q.id]==='r');
+  const all=[...mc,...wr];if(!all.length)return;
+  mc.forEach(q=>delete mcR[q.id]);
+  wr.forEach(q=>{delete wR[q.id];delete saved[q.id];});
+  qs=all;idx=0;
+  show('Q');render();
+}
+</script>
+</body>
+</html>


