+function tick(id){
+  const el=document.getElementById(id);
+  el.classList.toggle('done');
+  el.querySelector('.box').textContent=el.classList.contains('done')?'✓':'☐';
+}
+
+function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
+
+let answers={};
+document.querySelectorAll('[data-question]').forEach((q,qi)=>{
+  const list=q.querySelector('.options');
+  const fb=q.querySelector('.feedback');
+  shuffle([...list.children]).forEach(li=>list.appendChild(li));
+  list.querySelectorAll('li').forEach(li=>{
+    li.addEventListener('click',()=>{
+      if(li.classList.contains('locked'))return;
+      list.querySelectorAll('li').forEach(x=>x.classList.add('locked'));
+      const correct=li.dataset.correct==='true';
+      li.classList.add(correct?'correct':'wrong');
+      if(!correct)list.querySelectorAll('[data-correct="true"]').forEach(x=>x.classList.add('correct'));
+      answers[qi]=correct;
+      fb.style.display='block';
+      fb.className='feedback '+(correct?'ok':'bad');
+      fb.textContent=(correct?'✓ Correct. ':'✗ Not quite. ')+li.dataset.why;
+    });
+  });
+});
+
+function scoreQuiz(){
+  const total=document.querySelectorAll('[data-question]').length;
+  const got=Object.values(answers).filter(Boolean).length;
+  const answered=Object.keys(answers).length;
+  const sb=document.getElementById('quiz-score');
+  sb.style.display='block';
+  const pct=answered?Math.round(got/total*100):0;
+  if(answered<total){sb.style.background='#1e2a4a';sb.style.borderColor='#60a5fa';
+    sb.innerHTML=`<strong>${got}/${answered}</strong> answered (${total-answered} skipped)`;}
+  else if(pct===100){sb.style.background='#1a3a2a';sb.style.borderColor='#34d399';
+    sb.innerHTML='🎉 <strong>5/5</strong> — Perfect! Mark section 8 complete.';}
+  else if(pct>=60){sb.style.background='#2a2a1a';sb.style.borderColor='#fbbf24';
+    sb.innerHTML=`<strong>${got}/5</strong> (${pct}%) — Good. Review the missed ones.`;}
+  else{sb.style.background='#3a1a1a';sb.style.borderColor='#f87171';
+    sb.innerHTML=`<strong>${got}/5</strong> (${pct}%) — Re-read sections 1–4, then retry.`;}
+}
+</script>
