+  {t:'MCLK "1000000", SMCLK "4800000", ACLK "9400" — DCO, MODCLK, VLO',c:false,w:'SMCLK defaults to DCO like MCLK (they share the source set and reset behaviour); ACLK defaults to LFXT, not VLO.'},
+ ]
+},
